158: void accel_sim_framework::cleanup(unsigned finished_kernel) {
159:   trace_kernel_info_t *k = NULL;
160:   unsigned long long finished_kernel_cuda_stream_id = -1;
161:   for (unsigned j = 0; j < kernels_info.size(); j++) {
162:     k = kernels_info.at(j);
163:     if (k->get_uid() == finished_kernel ||
164:         m_gpgpu_sim->cycle_insn_cta_max_hit() || !m_gpgpu_sim->active()) {
165:       for (unsigned int l = 0; l < busy_streams.size(); l++) {
166:         if (busy_streams.at(l) == k->get_cuda_stream_id()) {
167:           finished_kernel_cuda_stream_id = k->get_cuda_stream_id();
168:           busy_streams.erase(busy_streams.begin() + l);
169:           break;
170:         }
171:       }
172:       tracer.kernel_finalizer(k->get_trace_info());
173:       delete k->entry();
174:       delete k;
175:       kernels_info.erase(kernels_info.begin() + j);
176:       if (!m_gpgpu_sim->cycle_insn_cta_max_hit() && m_gpgpu_sim->active())
177:         break;
178:     }
179:   }
180:   if (k) {
181:     m_gpgpu_sim->print_stats(finished_kernel_cuda_stream_id);
182:     m_gpgpu_sim->perf_counters.print_counters();
183:   }

186: unsigned accel_sim_framework::simulate() {
187:   unsigned finished_kernel_uid = 0;
188:   do {
189:     if (!m_gpgpu_sim->active()) break;
190: 
191:     // performance simulation
192:     if (m_gpgpu_sim->active()) {
193:       m_gpgpu_sim->cycle();
194:       sim_cycles = true;
195:       // Same-thread post-cycle observation; no queue pops, model writes or
196:       // unsynchronized timer reads. Long blocking phases fail freshness upstream.
197:       if (ag7_progress.enabled()) ag7_progress.observe("SIMULATE",
198:           m_gpgpu_sim->gpu_tot_sim_insn + m_gpgpu_sim->gpu_sim_insn, true, false,
199:           "NONE", busy_streams.size() == 1 ?
200:               static_cast<int64_t>(busy_streams.front()) : -1);
201:       m_gpgpu_sim->deadlock_check();
202:     } else {
203:       if (m_gpgpu_sim->cycle_insn_cta_max_hit()) {
204:         m_gpgpu_context->the_gpgpusim->g_stream_manager
205:             ->stop_all_running_kernels();
206:         break;
207:       }
208:     }
209: 
210:     active = m_gpgpu_sim->active();
211:     finished_kernel_uid = m_gpgpu_sim->finished_kernel();
212:   } while (active && !finished_kernel_uid);
213:   return finished_kernel_uid;

391: void gpgpu_context::print_simulation_time() {
392:   time_t current_time, difference, d, h, m, s;
393:   current_time = time((time_t *)NULL);
394:   difference = MAX(current_time - the_gpgpusim->g_simulation_starttime, 1);
395: 
396:   d = difference / (3600 * 24);
397:   h = difference / 3600 - 24 * d;
398:   m = difference / 60 - 60 * (h + 24 * d);
399:   s = difference - 60 * (m + 60 * (h + 24 * d));
400: 
401:   fflush(stderr);
402:   printf(
403:       "\n\ngpgpu_simulation_time = %u days, %u hrs, %u min, %u sec (%u sec)\n",
404:       (unsigned)d, (unsigned)h, (unsigned)m, (unsigned)s, (unsigned)difference);
405:   printf("gpgpu_simulation_rate = %u (inst/sec)\n",
406:          (unsigned)(the_gpgpusim->g_the_gpu->gpu_tot_sim_insn / difference));
407:   const unsigned cycles_per_sec =
408:       (unsigned)(the_gpgpusim->g_the_gpu->gpu_tot_sim_cycle / difference);
409:   printf("gpgpu_simulation_rate = %u (cycle/sec)\n", cycles_per_sec);
410: 
411:   if (cycles_per_sec == 0) {
412:     printf("gpgpu_silicon_slowdown = Nan\n");
413:   } else {
414:     printf("gpgpu_silicon_slowdown = %ux\n",
415:            the_gpgpusim->g_the_gpu->shader_clock() * 1000 / cycles_per_sec);
416:   }
417:   fflush(stdout);
418: }
